      d = 2 * d;
      v = 2 * v;
    }

    c = c - v;
    k = k + d;
  }

  a = b;
  b = c;
  int temp;
  temp = p;
  p = q;
  q = temp - (q * k);
  temp = r;
  r = s;
  s = temp - (s * k);
}

return 0;
}


